import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 38 The first calendar","description":"学习 目的不定式与 for doing，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 38 The first calendar","description":"学习 目的不定式与 for doing，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 目的不定式与 for doing，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 37 The Westhaven Express","link":"/life/english/new-concept/book-3/unit-02/lesson-037"},"next":{"text":"第三册：培养技能 · Lesson 39 Nothing to worry about","link":"/life/english/new-concept/book-3/unit-02/lesson-039"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 37 The Westhaven Express","link":"/life/english/new-concept/book-3/unit-02/lesson-037"},"next":{"text":"第三册：培养技能 · Lesson 39 Nothing to worry about","link":"/life/english/new-concept/book-3/unit-02/lesson-039"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-038.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-038.md"}'),r={name:"life/english/new-concept/book-3/unit-02/lesson-038.md"};function i(s,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-38-the-first-calendar" tabindex="-1">第三册：培养技能 · Lesson 38 The first calendar <a class="header-anchor" href="#第三册-培养技能-·-lesson-38-the-first-calendar" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 38 The first calendar&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从早期计时方法讨论观察、记录和推断，训练描述周期而不把证据解释为唯一结论。学习表示用途的不定式与动名词介词结构，说明人们为什么记录自然变化。重点是区别物品的设计用途、人的使用目的和根据痕迹提出的研究假设。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>cycle</td><td>/ˈsaɪkl/</td><td>n.</td><td>周期</td><td>a lunar cycle</td></tr><tr><td>record</td><td>/ˈrekɔːd/</td><td>n.</td><td>记录</td><td>keep a record</td></tr><tr><td>mark</td><td>/mɑːk/</td><td>v.</td><td>标记</td><td>mark a date</td></tr><tr><td>observe</td><td>/əbˈzɜːv/</td><td>v.</td><td>观察</td><td>observe the moon</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep track of — 持续记录并掌握进度</li><li>in order to — 为了做某事</li></ul><h2 id="语法讲解-目的不定式与-for-doing" tabindex="-1">语法讲解：目的不定式与 for doing <a class="header-anchor" href="#语法讲解-目的不定式与-for-doing" aria-label="Permalink to &quot;语法讲解：目的不定式与 for doing&quot;">​</a></h2><p>to do 常说明行为目的，即某人为了什么采取行动；for doing 常说明物品用途或某种功能。A tool for measuring 是测量工具，He used a tool to measure 说明他使用工具的目的。in order to 更明确地标出目的，否定写 in order not to。不是所有 for 加 ing 都表示目的，也可能表示原因或感谢对象，应根据动词搭配判断。讨论古物用途时，may have been used to ... 保留推断空间，不能将可能用途写成确定事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The group marked a stone each evening to keep track of passing days.</p></blockquote><p>这群人每天晚上在石头上做记号，以记录日子的推移。</p><p>marked 为主要动作，to keep track of 为目的；each evening 说明重复频率。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>a tool for measure 应为 a tool for measuring；目的不定式则是 used it to measure。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 to mark 与 for marking，注意两种用途表达的不同词尾；再不看文本说明红珠子的功能。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We place one bead in a jar to mark each day. A red bead marks the start of a new week. The system fails if someone forgets to add a bead.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>设计一种虚构的简单记录法，用三句说明材料、操作和限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>目的清楚，规则可操作，并指出依赖持续执行这一限制。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句的目的部分从哪个词开始？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> to keep track of ... 说明标记的目的。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：This is a device for ___ time.（measuring/measure）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> measuring</p><p><strong>解析：</strong> 介词 for 后用动名词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“不漏掉一天”接在 in order 后。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> in order not to miss a day</p><p><strong>解析：</strong> 否定词放在 to 前。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：目的不定式与 for doing。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-039">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(r,[["render",i]]);export{u as __pageData,f as default};
